-- Receipt storage keys are generated by the server (receipts/<year>/<uuid>.<ext>). A seller can insert
-- ledger_receipts rows through PostgREST, so the key format is enforced here: no path segments of
-- their choosing, no pointing at other objects, and the extension must match the recorded type.
alter table public.ledger_receipts
  add constraint ledger_receipts_key_format check (
    storage_key ~ '^receipts/[0-9]{4}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|png|webp|heic|pdf)$'
    and right(storage_key, length(storage_key) - position('.' in storage_key)) = case mime_type
      when 'image/jpeg' then 'jpg'
      when 'image/png' then 'png'
      when 'image/webp' then 'webp'
      when 'image/heic' then 'heic'
      when 'application/pdf' then 'pdf'
    end
  );
